import{_ as a,o as n,c as e,a2 as t}from"./chunks/framework.Bx7X8BVG.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1790778157000}'),i={name:"guide/index.md"};function l(r,s,p,d,o,c){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>从零到一条隧道跑通，大约 3 分钟。需要你手上有 <strong>一个托管在 Cloudflare 的域名</strong>（免费套餐足够）。</p><h2 id="第一步-部署" tabindex="-1">第一步：部署 <a class="header-anchor" href="#第一步-部署" aria-label="Permalink to &quot;第一步：部署&quot;">​</a></h2><p>SSH 到你的 NAS 或服务器：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 下载项目（国内直连 GitHub 不稳时，用第二行的镜像地址）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/lieren2012/cloudflare-tunnel-manager.git</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># git clone https://v4.gh-proxy.org/https://github.com/lieren2012/cloudflare-tunnel-manager.git</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 构建并启动</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloudflare-tunnel-manager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>构建会自动从 <code>docker.1ms.run</code> 拉取基础镜像、从 <code>registry.npmmirror.com</code> 装 npm 依赖，国内一般 1~3 分钟。</p><div class="tip custom-block"><p class="custom-block-title">首次构建较慢是正常的</p><p>主要耗时在拉取 <code>node:22-alpine</code> 和 <code>cloudflare/cloudflared</code> 两个基础镜像（合计约 100MB）。第二次重建会用缓存，几秒就好。</p></div><h2 id="第二步-打开面板" tabindex="-1">第二步：打开面板 <a class="header-anchor" href="#第二步-打开面板" aria-label="Permalink to &quot;第二步：打开面板&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://你的NAS地址:19090</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>首次打开会引导你<strong>注册管理员账户</strong>——第一个注册的用户自动成为管理员。</p><div class="warning custom-block"><p class="custom-block-title">记住这个密码</p><p>管理员密码用于管理用户与凭据。忘了可以在 NAS 上给容器设 <code>ADMIN_PASSWORD</code> 环境变量走紧急恢复通道，或用 <code>master</code> 作为用户名登录。</p></div><h2 id="第三步-填入-cloudflare-凭据" tabindex="-1">第三步：填入 Cloudflare 凭据 <a class="header-anchor" href="#第三步-填入-cloudflare-凭据" aria-label="Permalink to &quot;第三步：填入 Cloudflare 凭据&quot;">​</a></h2><p>进入「<strong>⚙️ 系统配置</strong>」页面，需要填两样东西：</p><table tabindex="0"><thead><tr><th>字段</th><th>从哪来</th></tr></thead><tbody><tr><td>账号 ID（Account ID）</td><td>Cloudflare 后台右侧栏复制</td></tr><tr><td>API Token</td><td>自建一个自定义令牌，只给两条权限</td></tr></tbody></table><p>具体步骤见 <strong><a href="/cloudflare-tunnel-manager/get-credentials">获取 Cloudflare 凭据</a></strong>（3 步，1 分钟）。</p><p>填完点「<strong>测试配置</strong>」，显示通过后点「<strong>保存配置</strong>」。</p><h2 id="第四步-建第一条隧道" tabindex="-1">第四步：建第一条隧道 <a class="header-anchor" href="#第四步-建第一条隧道" aria-label="Permalink to &quot;第四步：建第一条隧道&quot;">​</a></h2><ol><li><p>进入「<strong>Tunnel 列表</strong>」→ 点「<strong>新建 Tunnel</strong>」，输入一个名字（例如 <code>nas</code>）</p></li><li><p>点这条隧道的「<strong>连接</strong>」——日志出现 <code>Registered tunnel connection connIndex=0</code> 就说明通了</p></li><li><p>点「<strong>路由</strong>」→ 添加规则：</p><table tabindex="0"><thead><tr><th>字段</th><th>示例</th></tr></thead><tbody><tr><td>域名</td><td><code>nas.example.com</code></td></tr><tr><td>服务</td><td><code>http://192.168.1.10:5000</code></td></tr></tbody></table><p>保存后会自动在 Cloudflare 创建 DNS CNAME 记录，浏览器打开 <code>https://nas.example.com</code> 就能访问你的内网服务了。</p></li><li><p>打开这条隧道的「<strong>自启</strong>」开关，容器重启后会自动重连（相当于开机自启）。</p></li></ol><div class="tip custom-block"><p class="custom-block-title">想要随机域名？</p><p>先在「系统配置 → 默认域名」里填好你的主域名（如 <code>example.com</code>），之后在路由弹窗里点「🎲」就能一键生成随机二级域名，不用自己想名字。</p></div><h2 id="服务端口" tabindex="-1">服务端口 <a class="header-anchor" href="#服务端口" aria-label="Permalink to &quot;服务端口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端口</th><th>服务</th><th>说明</th></tr></thead><tbody><tr><td><strong>19090</strong></td><td>Web 管理面板</td><td>你日常用的界面</td></tr><tr><td><strong>19092</strong></td><td>外部 REST API</td><td>给别的程序调用，<code>X-API-Key</code> 鉴权</td></tr><tr><td><strong>19093</strong></td><td>MCP 服务</td><td>给 AI 客户端接入，<code>X-API-Key</code> 鉴权</td></tr></tbody></table><p>详见 <strong><a href="/cloudflare-tunnel-manager/guide/api">外部 API 与 MCP</a></strong>。</p><h2 id="目录与数据" tabindex="-1">目录与数据 <a class="header-anchor" href="#目录与数据" aria-label="Permalink to &quot;目录与数据&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cloudflare-tunnel-manager/</span></span>
<span class="line"><span>├── src/            后端源码</span></span>
<span class="line"><span>├── public/         前端源码</span></span>
<span class="line"><span>├── data/           ★ 你的数据（不在 git 里，更新不受影响）</span></span>
<span class="line"><span>│   ├── config.json    Cloudflare 凭据、站点设置、更新源</span></span>
<span class="line"><span>│   ├── tunnels.json   隧道与分组</span></span>
<span class="line"><span>│   ├── users.json     用户账户</span></span>
<span class="line"><span>│   └── sessions.json  登录会话</span></span>
<span class="line"><span>├── docker-compose.yml</span></span>
<span class="line"><span>└── update.sh       命令行更新脚本</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><div class="danger custom-block"><p class="custom-block-title">一定要备份 data/ 目录</p><p>所有凭据、用户、隧道配置都在这里。<code>git reset --hard</code> 之类的代码更新不会碰它，但你自己手动删目录前请先备份。</p></div><h2 id="网络模式说明" tabindex="-1">网络模式说明 <a class="header-anchor" href="#网络模式说明" aria-label="Permalink to &quot;网络模式说明&quot;">​</a></h2><p>默认使用 <code>network_mode: host</code>——这样隧道进程能直接访问宿主机内网（例如 <code>192.168.x.x</code> 上的服务），无需额外配置。</p><p>如果你必须用 bridge 网络，把 compose 里的 <code>network_mode: host</code> 换成端口映射，并把隧道服务地址改成<strong>宿主机 IP</strong>：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;19090:19090&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;19092:19092&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;19093:19093&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="不用-docker-的话" tabindex="-1">不用 Docker 的话 <a class="header-anchor" href="#不用-docker-的话" aria-label="Permalink to &quot;不用 Docker 的话&quot;">​</a></h2><p>需要 Node.js 18+ 和本机已安装 <code>cloudflared</code>（或用 <code>CLOUDFLARED_PATH</code> 指定路径）：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><strong><a href="/cloudflare-tunnel-manager/guide/panel">管理面板</a></strong> —— 隧道管理、设备分组、多用户、站点设置</li><li><strong><a href="/cloudflare-tunnel-manager/guide/update">更新与国内加速</a></strong> —— 面板内一键更新怎么用</li><li><strong><a href="/cloudflare-tunnel-manager/guide/security">安全与公网暴露</a></strong> —— 准备把面板放到公网前务必看</li></ul>`,34)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
